import{c as s,Q as t,j as i,m as a}from"./chunks/framework.CyZn50Me.js";const u=JSON.parse('{"title":"Mission trajectories — operator guide","description":"","frontmatter":{},"headers":[],"relativePath":"guides/mission-trajectories.md","filePath":"guides/mission-trajectories.md"}'),o={name:"guides/mission-trajectories.md"};function r(n,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="mission-trajectories-—-operator-guide" tabindex="-1">Mission trajectories — operator guide <a class="header-anchor" href="#mission-trajectories-—-operator-guide" aria-label="Permalink to &quot;Mission trajectories — operator guide&quot;">​</a></h1><p>Companion to <a href="./../adr/ADR-058">ADR-058</a>. Covers how to add a new mission&#39;s trajectory waypoints + phase markers + science chips to <code>/fly</code>. The same toolchain applies to Moon (cislunar) + Mars + outer-system (heliocentric) missions.</p><hr><h2 id="quick-reference" tabindex="-1">Quick reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mission destination</th><th>Schema field</th><th>Generator script</th><th>Coordinate system</th></tr></thead><tbody><tr><td>Moon</td><td><code>flight.cislunar_profile.waypoints_km</code></td><td><code>scripts/cislunar/generate-hybrid-waypoints.ts</code></td><td>ECI km</td></tr><tr><td>Mars + outer-system</td><td><code>flight.interplanetary_profile.waypoints_helio_au</code></td><td><code>scripts/cislunar/generate-helio-hybrid-waypoints.ts</code></td><td>Heliocentric AU</td></tr></tbody></table><p>Both ship at <strong><code>source_tier: tier_1_5_hybrid</code></strong> by default — analytic curve resampled to 100 waypoints with event-MET anchors pinned to slot indices. <code>tier_2_published</code> is reserved for direct NASA TND / ESA SPICE ingest (future slice).</p><hr><h2 id="adding-a-new-mission" tabindex="-1">Adding a new mission <a class="header-anchor" href="#adding-a-new-mission" aria-label="Permalink to &quot;Adding a new mission&quot;">​</a></h2><p>Assuming the mission&#39;s JSON is at <code>static/data/missions/&lt;dest&gt;/&lt;slug&gt;.json</code> with <code>flight.events[]</code> and either <code>flight.cislunar_profile</code> (Moon) or <code>flight.interplanetary_profile</code> (Mars / outer) populated at least with parametric defaults.</p><h3 id="moon-mission" tabindex="-1">Moon mission <a class="header-anchor" href="#moon-mission" aria-label="Permalink to &quot;Moon mission&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/cislunar/generate-hybrid-waypoints.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> static/data/missions/moon/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.json</span></span></code></pre></div><p>The generator:</p><ol><li>Reads <code>flight.cislunar_profile</code> parametric fields + <code>flight.events[].met_days</code>.</li><li>Calls <code>buildCislunarTrajectory()</code> (same path the renderer uses).</li><li>Resamples to 100 MET-evenly-spaced waypoints across the mission window. Window = max(<code>transit_days × multiplier</code>, <code>latest_event_met × 1.05</code>); multiplier is 2 when <code>cislunar_profile.return.type != &#39;none&#39;</code>, else 1.</li><li>Pins event-MET anchors to nearest slot indices (so the phase markers land exactly at published METs).</li><li>Writes <code>waypoints_km</code> + flips <code>source_tier</code> to <code>tier_1_5_hybrid</code>.</li></ol><h3 id="mars-outer-system-mission" tabindex="-1">Mars / outer-system mission <a class="header-anchor" href="#mars-outer-system-mission" aria-label="Permalink to &quot;Mars / outer-system mission&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/cislunar/generate-helio-hybrid-waypoints.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> static/data/missions/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mars</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ceres</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jupiter</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neptune</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pluto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;slug&gt;.json</span></span></code></pre></div><p>Same pattern but for heliocentric AU coords. Reads <code>departure_date</code> + <code>arrival_date</code> (top-level), <code>transit_days</code>, and <code>flight.events[]</code>. Builds a transfer ellipse via <code>transferEllipse()</code> from <code>mission-arc.ts</code>, samples to 100 points, pins event METs. Writes <code>waypoints_helio_au</code> (units: AU, with <code>y = 0</code> for in-plane transfers, which covers all current missions). Flips <code>source_tier</code> to <code>tier_1_5_hybrid</code>.</p><h3 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate-data</span></span></code></pre></div><p>The waypoint validators (<code>checkCislunarWaypoints</code> + <code>checkInterplanetaryWaypoints</code> in <code>scripts/validate-data.ts</code>) enforce:</p><ul><li><code>waypoints[0].met_days == 0</code> (launch anchor)</li><li>Strictly-increasing METs</li><li>Mission window cap</li><li>200-waypoint hard cap</li><li>Heliocentric radius sanity (0.1–50 AU)</li></ul><p>For visual spot-check, run <code>npm run preview</code> and open <code>/fly?mission=&lt;slug&gt;</code>. Phase markers should render on the trajectory in both 3D and 2D views, with science chips on the HUD phase pill.</p><hr><h2 id="edge-cases" tabindex="-1">Edge cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge cases&quot;">​</a></h2><h3 id="missions-whose-timeline-extends-past-transit-days" tabindex="-1">Missions whose timeline extends past <code>transit_days</code> <a class="header-anchor" href="#missions-whose-timeline-extends-past-transit-days" aria-label="Permalink to &quot;Missions whose timeline extends past `transit_days`&quot;">​</a></h3><p>Some missions have events past the nominal outbound transit (Apollo 13&#39;s return after the anomaly; Apollo 17&#39;s lunar surface stay; Beresheet&#39;s late-impact anomaly; Voyager 2&#39;s outer-planet flybys). The generator&#39;s window calc handles this — <code>latest_event_met × 1.05</code> overrides <code>transit_days × multiplier</code> when the events extend further. The validator allows up to <code>latest_event_met × 1.1</code>.</p><h3 id="mission-without-a-published-trajectory-shape" tabindex="-1">Mission without a published trajectory shape <a class="header-anchor" href="#mission-without-a-published-trajectory-shape" aria-label="Permalink to &quot;Mission without a published trajectory shape&quot;">​</a></h3><p>For speculative / planned missions with <code>transit_days</code> + dates but no event timeline yet, leave the trajectory at <code>tier_1_analytic</code> — <code>/fly</code> will still render the parametric path via <code>buildCislunarTrajectory()</code> / <code>buildInterplanetaryTrajectory()</code> directly. Examples currently at <code>tier_1_analytic</code>: <code>starship-demo</code>, <code>starship-mars-crew</code> (0-event speculative Mars missions).</p><h3 id="truncated-trajectories-impacts-anomalies" tabindex="-1">Truncated trajectories (impacts, anomalies) <a class="header-anchor" href="#truncated-trajectories-impacts-anomalies" aria-label="Permalink to &quot;Truncated trajectories (impacts, anomalies)&quot;">​</a></h3><p>Beresheet ends with an <code>anomaly</code> event at MET 48.01d (impact on the Moon). The generator includes events beyond <code>transit_days</code> cleanly because of the window-extension rule; the renderer linearly interpolates waypoints, so the trajectory visually terminates at the last waypoint. The phase-marker reveal state machine flags any event with <code>met_days &gt; simDay</code> as <code>ghosted</code>.</p><h3 id="sample-return-missions" tabindex="-1">Sample-return missions <a class="header-anchor" href="#sample-return-missions" aria-label="Permalink to &quot;Sample-return missions&quot;">​</a></h3><p><strong>Moon (<code>cislunar_profile.return.type</code>):</strong> Set to one of:</p><ul><li><code>none</code> (default — one-way; flyby missions, impactors, orbiters that stay)</li><li><code>tei_direct</code> (direct Trans-Earth Injection)</li><li><code>tei_lor</code> (Lunar Orbit Rendezvous on return)</li></ul><p>The generator multiplies the transit window by 2 to cover both outbound + return. Examples: Apollo 11/13/17, Chang&#39;e 5/6, Artemis 2, sample-return Luna missions.</p><p><strong>Mars + outer-system (<code>interplanetary_profile.return.type</code>):</strong> Same shape, different enum:</p><ul><li><code>none</code> (default — every current Mars + outer-system mission)</li><li><code>tei_helio_direct</code> (direct heliocentric Trans-Earth Injection)</li><li><code>tei_helio_lor</code> (LOR-pattern adapted to interplanetary range)</li></ul><p>Example: MMX (JAXA Mars/Phobos sample return, 2026) is planned as sample-return; when its event timeline is backfilled with <code>earth_return</code>, set <code>interplanetary_profile.return.type = &quot;tei_helio_direct&quot;</code> so /fly renders both legs.</p><h3 id="outer-system-missions-galileo-voyager-2-new-horizons-dawn" tabindex="-1">Outer-system missions (Galileo, Voyager 2, New Horizons, Dawn) <a class="header-anchor" href="#outer-system-missions-galileo-voyager-2-new-horizons-dawn" aria-label="Permalink to &quot;Outer-system missions (Galileo, Voyager 2, New Horizons, Dawn)&quot;">​</a></h3><p>Outer-system missions use the same <code>interplanetary_profile</code> schema as Mars. Differences worth knowing:</p><ul><li><strong>Multiple flybys past target body.</strong> Voyager 2 (Grand Tour: Jupiter → Saturn → Uranus → Neptune) and Galileo (Venus + 2× Earth + 2× asteroid gravity assists before Jupiter arrival) have events extending well past <code>transit_days</code> (Voyager 2: 4607d events vs 4388d transit). The window-extension rule covers this automatically.</li><li><strong>No descent / EDL.</strong> Most outer-system missions are flybys or orbit-only — the cislunar <code>descent</code> / <code>ascent</code> / <code>edl</code> event types don&#39;t apply. Use <code>flyby</code>, <code>arrival</code>, <code>edl_or_oi</code> (for atmospheric probes like Galileo&#39;s Jupiter probe) as appropriate.</li><li><strong>arrival_body enum.</strong> Set to one of <code>ceres</code>, <code>jupiter</code>, <code>neptune</code>, <code>pluto</code>. The generator&#39;s <code>destinationPos()</code> provides the correct heliocentric position at arrival; Mars-specific <code>marsPos()</code> is bypassed.</li><li><strong>No sample-return.</strong> All current outer-system missions are one-way; leave <code>return.type</code> absent.</li></ul><hr><h2 id="phase-types-science-map" tabindex="-1">Phase types + science map <a class="header-anchor" href="#phase-types-science-map" aria-label="Permalink to &quot;Phase types + science map&quot;">​</a></h2><p>The science cross-links on the HUD phase pill + per-event marker chips are configured in <code>static/data/cislunar-phase-science-map.json</code>. Two key sections:</p><ul><li><code>phase_refs</code>: maps <code>CislunarPhaseType</code> (10 cislunar) + <code>InterplanetaryPhaseType</code> (11 heliocentric) to <code>/science/&lt;tab&gt;/&lt;slug&gt;</code> references.</li><li><code>event_refs</code>: maps <code>FlightEventType</code> (14 event types) to <code>/science/&lt;tab&gt;/&lt;slug&gt;</code> references.</li></ul><p>A reference takes the form <code>[{ &quot;tab&quot;: &quot;mission-phases&quot;, &quot;slug&quot;: &quot;trans-x-injection&quot; }, ...]</code> — first entry is the primary chip, additional entries appear in the panel&#39;s expanded view.</p><p>When adding a new event or phase type:</p><ol><li>Update the schema&#39;s <code>FlightEventType</code> / phase enums (<code>src/types/mission.ts</code> + <code>static/data/schemas/mission.schema.json</code>).</li><li>Add a <code>phase_refs</code> or <code>event_refs</code> entry pointing at an existing <code>/science/&lt;tab&gt;/&lt;slug&gt;.json</code> page. Run <code>npx tsx scripts/cislunar/check-science-map-refs.ts</code> to verify it resolves.</li><li>Add an i18n label in <code>messages/en-US.json</code> (<code>fly_event_&lt;type&gt;</code> for events). Mirror to all 14 locales (uppercase aerospace shorthand convention — same EN string across non-EN locales).</li><li>Extend the <code>defaultEventLabel()</code> switch in <code>src/routes/fly/+page.svelte</code>.</li></ol><hr><h2 id="scrubber-ux-107-step-6g" tabindex="-1">Scrubber UX (#107 Step 6g) <a class="header-anchor" href="#scrubber-ux-107-step-6g" aria-label="Permalink to &quot;Scrubber UX (#107 Step 6g)&quot;">​</a></h2><p>Phase marker dots are clickable buttons that jump the sim to that event&#39;s MET. Driven by:</p><ul><li><code>PhaseMarkerLabel.svelte</code> props: <code>onJump: () =&gt; void</code> + <code>eventMetDays: number</code>.</li><li><code>/fly</code>&#39;s <code>jumpToMet(metDays)</code> handler sets <code>simDay = depDay + met</code>, pauses sim.</li></ul><p>Keyboard-focusable; aria-label includes the MET (&quot;LOI at MET 3.13 days. Click to jump.&quot;). Reduced-motion: snap, no animation.</p><hr><h2 id="real-nasa-tnd-state-vector-ingest-tier-2-published" tabindex="-1">Real NASA TND state-vector ingest (<code>tier_2_published</code>) <a class="header-anchor" href="#real-nasa-tnd-state-vector-ingest-tier-2-published" aria-label="Permalink to &quot;Real NASA TND state-vector ingest (`tier_2_published`)&quot;">​</a></h2><p>Currently deferred to v0.8+ (tracked as <strong><a href="https://github.com/chipi/orrery/issues/262" target="_blank" rel="noreferrer">GH #262</a></strong>). When implemented, the ingest path will:</p><ul><li>Read NASA Mission Report PDFs (Apollo 11 MSC-00171, Apollo 13 MSC-02680, Apollo 17 JSC-07904, Artemis II post-flight reconstruction).</li><li>Parse the state-vector tables (each Mission Report has its own table format — per-mission adapter).</li><li>Emit <code>waypoints_km</code> directly with <code>source_tier: tier_2_published</code>.</li><li>Visual delta vs. the <code>tier_1_5_hybrid</code> curve should be within a few percent (geometry is already faithful to first-order).</li></ul><p>The reserved tier label exists in the schema enums today; only the ingest path is open. Same shape applies to a future Mars / outer-system <code>tier_2_published</code> path via JPL Horizons or ESA SPICE state-vector kernels.</p><hr><p><em>Orrery · mission-trajectories.md · #107 Step 6 — May 2026</em></p>',58)])])}const m=s(o,[["render",r]]);export{u as __pageData,m as default};
